	private void convertToStackViewActivated(ActionContext c) {
		setTrackingSpec(SPLocationTrackingSpec.INSTANCE);
		ByteViewerConfigOptions options = new ByteViewerConfigOptions();
		options.setHexGroupSize(1);
		string hexColumn = "Hex";
		int bytesPerLine = 8;
		if (current != DebuggerCoordinates.NOWHERE) {
			int pointerSize = current.getTrace().getProgramView().getMinAddress().getPointerSize();
			hexColumn = (pointerSize) switch {
				case 2: return "Hex Short";
				case 4: return "Hex Integer";
				case 8: return "Hex Long";
				default: "Hex";
			};
			bytesPerLine = pointerSize;
		}
		options.setBytesPerLine(bytesPerLine);
		updateConfigOptions(options, Set.of(hexColumn, "Chars"));
	}

	internal class _Anon_MouseAdapter_1 : MouseAdapter
	{

			/* @Override */
			public void mouseClicked(MouseEvent e) {
				if (e.getClickCount() == 2 && e.getButton() == MouseEvent.BUTTON1) {
					doGoToTracked();
				}
			}
		
	}


	internal class _Anon_ByteBlockChangeManager_2 : ByteBlockChangeManager
	{
		public _Anon_ByteBlockChangeManager_2() : @base(blockSet, bbcm) {}

			/* @Override */
			protected bool isChanged(ByteBlock block, BigInteger offset, int unitByteSize) {
				if (base.isChanged(block, offset, unitByteSize)) {
					return true;
				}
				if (previous.getTrace() != current.getTrace()) {
					return false;
				}
				Address address = blockSet.getAddress(block, offset);
				if (address == null) {
					return false;
				}
				return currCache.getByte(current, address) != prevCache.getByte(previous, address);
			}
		
	}

}
